with unpacked as (select id, plan, currency, discounts, array_min(tier_prices) as lowest_price, aggregate(tier_prices, cast(0 as double), (acc, p) -> acc + p, acc -> round(acc / size(tier_prices), 2)) as avg_tier_price, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices, element_at(tier_prices, 1) as entry_price, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps from price_tiers where plan = 'pro') select id, plan, lowest_price, avg_tier_price, min(lowest_price) over (partition by plan order by avg_tier_price, id rows between 3 preceding and current row) as last4_min_lowest_price, avg(lowest_price) over (partition by plan order by avg_tier_price, id rows between 3 preceding and current row) as last4_avg_lowest_price, count(lowest_price) over (partition by plan order by avg_tier_price, id rows between 3 preceding and current row) as last4_count_lowest_price, last_value(avg_tier_price) ignore nulls over (order by entry_price, id rows between unbounded preceding and current row) as last_known_avg_tier_price from unpacked;
